from taf.rfrl.l3_call.cell.classical_cell.classical_cell import ClassicalCell
from taf.rfrl.l3_call.cell.exceptions import CellIdNotFound
from taf.rfrl.l3_call.logger.l3_call_logger import log_input_and_output, log_to_console


class ClassicalLteCell(ClassicalCell):
    def __init__(self, cell_distname, bts_connection_alias, shared_spectrum):
        super(ClassicalLteCell, self).__init__(cell_distname, bts_connection_alias, shared_spectrum)
        self._type = "lte"

    def __str__(self):
        return "ClassicalLnCell cell instance for {0} cell type".format(self._type)

    def _is_beamforming_activated(self):
        return False

    def _make_callable(self, delta):
        log_to_console("Making cell {} callable".format(self.distname))
        if not self._check_blocking_state(expected_state="Unblocked"):
            self._unblock_cell()
            self._check_blocking_state(expected_state="Unblocked")

        distname = self.distname + "/SIB-0"
        if delta:
            log_to_console("Adding cellBarred parameter update for cell {} to delta".format(self.distname))
            delta.add_parameter_to_delta(dist_name=distname, parameter="cellBarred", value="notBarred")
        else:
            self._change_cellbarred_parameter(value="notBarred", cell_distname=distname)

    def _make_uncallable(self, delta):
        if self._shared_spectrum and not self._check_blocking_state(expected_state="Blocked"):
            log_to_console("Blocking cell {}".format(self.distname))
            self._block_cell()
            self._check_blocking_state(expected_state="Blocked")

        if not self._shared_spectrum and not self._check_blocking_state(expected_state="Blocked"):
            log_to_console("Adding cellBarred parameter update for cell {} to delta".format(self.distname))
            delta.add_parameter_to_delta(dist_name=self.distname + "/SIB-0", parameter="cellBarred",
                                         value="barred")

    def _make_barred(self, delta):
        log_to_console("Adding cellBarred parameter update for cell {} to delta".format(self.distname))
        delta.add_parameter_to_delta(dist_name=self.distname + "/SIB-0", parameter="cellBarred", value="barred")

    def _make_unbarred(self, delta):
        log_to_console("Adding cellBarred parameter update for cell {} to delta".format(self.distname))
        delta.add_parameter_to_delta(dist_name=self.distname + "/SIB-0", parameter="cellBarred", value="notBarred")

    def _get_dss_pair(self):
        dss_info = self._api.get_managed_objects(connection=self._connection,
                                                 class_name="NRDSSLTE_A")
        for dss_nr in dss_info:
            physical_cell_id_lte = self._get_physical_cell_id_using_configuration_distname(
                configuration_distname=self.distname,
                cell_type="lte"
            )
            if dss_nr["parameters"]["ltePhyCellId"] == physical_cell_id_lte:
                return self._get_configuration_distname_using_cell_id(
                    cell_id=dss_nr["distName"].split("/")[-2].split("-")[-1],
                    cell_type="nr"
                )

    @log_input_and_output
    def _get_cell_id(self):
        cells_info = self._api.get_cells_info(connection=self._connection, cell_type="lte")
        for cell in cells_info:
            if cell["id"]["configuration"] == self.distname:
                return cell["eutranCellId"]

        raise CellIdNotFound("Cell ID not found for cell {}".format(self.distname))

    def _get_carrier_frequency_and_channel_bandwidth(self, cells_info, cell_specific_info):
        channel_bandwidth = self._get_channel_bandwidth(cell_specific_info=cell_specific_info)
        carrier_frequency = cell_specific_info["downlinkFrequency"]

        return float(channel_bandwidth.replace("MHz", "")), int(carrier_frequency)

    @log_input_and_output
    def _get_protocol_for_pcap_verification(self):
        return "s1ap"

    @log_input_and_output
    def _get_ok_msgs_and_procedure_codes(self):
        return {
            "InitialUEMessage": 12,
            "UECapabilityInfoIndication": 22,
            "InitialContextSetupResponse": 9
        }

    @log_input_and_output
    def _get_nok_msgs_and_procedure_codes(self):
        return {
            "UEContextReleaseComplete": 5
        }

    @log_input_and_output
    def _get_nok_structures(self):
        return []
